styles:
    *,
    *::before,
    *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html,
    body {
      height: 100%;
    }

    :root {
      --blue: #448AFF;
      --blue-dark: #3a7aee;
      --blue-btn: #3d82f0;
      --cream: #FFFEF4;
      --text: #1a1a1a;
      --muted: #8e8e8e;
      --input-bg: rgba(68, 138, 255, 0.06);
      --placeholder: #b0b0b0;
      --required: #e53935;
      --blue-ring: rgba(68, 138, 255, 0.15);
      --input-radius: 10px;
      --strength-weak: #e53935;
      --strength-medium: #f5a623;
      --strength-strong: #43a047;
      --match-ok: #43a047;
      --match-error: #e53935;
    }

    body {
      font-family: 'Montserrat', sans-serif;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      min-height: 100vh;
      background: linear-gradient(
        180deg,
        #DBE8FF 0%,
        #8AB6FF 27%,
        #448AFF 50%,
        #8AB6FF 77%,
        #DBE8FF 100%
      );
    }

    .shell {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(calc(550px + 112px), 1fr);
      min-height: 100vh;
      width: 100%;
    }

    .hero {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      text-align: center;
      color: #fff;
      padding: 48px 32px;
    }

    .logo-wrap {
      display: flex;
      justify-content: center;
      line-height: 0;
      margin-bottom: -30px;
    }

    .logo {
      width: 260px;
      height: auto;
      display: block;
      mix-blend-mode: screen;
      filter: drop-shadow(0 6px 12px rgba(0, 40, 80, 0.12));
    }

    .greeting {
      font-size: 28px;
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 12px;
      color: #fff;
    }

    .hero-sub {
      font-size: 13px;
      font-weight: 400;
      margin-bottom: 28px;
      opacity: 0.95;
    }

    .btn-signin-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-width: 175px;
      height: 40px;
      padding: 0 22px;
      border: none;
      border-radius: 8px;
      background: var(--blue-btn);
      color: #fff;
      font-family: 'Montserrat', sans-serif;
      font-size: 12px;
      font-weight: 800;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      text-decoration: none;
      cursor: pointer;
      box-shadow: 0 6px 16px rgba(0, 50, 120, 0.22);
      transition: background 0.15s ease, transform 0.1s ease;
    }

    .btn-arrow {
      width: 18px;
      height: 18px;
      flex-shrink: 0;
    }

    .btn-signin-link:hover {
      background: var(--blue-dark);
    }

    .btn-signin-link:active {
      transform: scale(0.99);
    }

    .form-panel {
      display: flex;
      align-items: flex-start;
      justify-content: flex-start;
      background: var(--cream);
      border-radius: 0;
      box-shadow: -12px 0 40px rgba(0, 40, 90, 0.1);
      padding: 36px 56px 40px 56px;
      margin-left: -24px;
      min-height: 100vh;
    }

    .form-inner {
      width: 550px;
      max-width: 100%;
      display: flex;
      flex-direction: column;
      text-align: left;
    }

    .page-title {
      font-size: 30px;
      font-weight: 700;
      color: var(--blue);
      margin-bottom: 26px;
      line-height: 1.15;
    }

    .section-title {
      font-size: 19px;
      font-weight: 700;
      color: var(--text);
      margin-bottom: 20px;
    }

    .form-inner form {
      width: 100%;
    }

    .form-group {
      margin-bottom: 20px;
    }

    .form-group:last-of-type {
      margin-bottom: 0;
    }

    .form-group label {
      display: block;
      font-size: 13px;
      font-weight: 700;
      color: var(--text);
      margin-bottom: 6px;
    }

    .form-group label .req {
      color: var(--required);
    }

    .input-wrap {
      position: relative;
    }

    .form-group input {
      width: 100%;
      height: 44px;
      padding: 0 42px 0 16px;
      border: 1.5px solid transparent;
      border-radius: var(--input-radius);
      background: var(--input-bg);
      font-family: 'Montserrat', sans-serif;
      font-size: 13px;
      font-weight: 400;
      color: var(--text);
      outline: none;
      box-shadow: inset 0 1px 2px rgba(0, 40, 90, 0.03);
      transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
    }

    .form-group input::placeholder {
      color: var(--placeholder);
      font-style: italic;
      font-weight: 400;
      font-size: 13px;
    }

    .form-group input:focus {
      border-color: var(--blue);
      background: #fff;
      box-shadow: 0 0 0 3px var(--blue-ring);
    }

    .toggle-password {
      z-index: 2;
      position: absolute;
      right: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 22px;
      height: 22px;
      padding: 0;
      border: none;
      background: transparent;
      color: #b0b0b0;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .toggle-password svg {
      position: absolute;
      width: 20px;
      height: 20px;
      display: block;
    }

    .toggle-password:hover {
      color: var(--text);
    }

    .toggle-password .icon-eye-off {
      display: block;
    }

    .toggle-password .icon-eye-on {
      display: none;
    }

    .toggle-password.is-visible .icon-eye-off {
      display: none;
    }

    .toggle-password.is-visible .icon-eye-on {
      display: block;
    }

    .strength-wrap {
      margin-top: 10px;
    }

    .strength-checklist {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 6px 14px;
      list-style: none;
      font-size: 11px;
      color: var(--muted);
    }

    .strength-checklist li {
      position: relative;
      padding-left: 14px;
      line-height: 1.35;
    }

    .strength-checklist li::before {
      content: '';
      position: absolute;
      left: 0;
      top: 4px;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #d3cec1;
      transition: background-color 0.22s ease;
    }

    .strength-checklist li.is-met {
      color: var(--text);
    }

    .strength-checklist.is-weak li.is-met::before {
      background: var(--strength-weak);
    }

    .strength-checklist.is-medium li.is-met::before {
      background: var(--strength-medium);
    }

    .strength-checklist.is-strong li.is-met::before {
      background: var(--strength-strong);
    }

    .match-message {
      margin-top: 8px;
      font-size: 11px;
      font-weight: 600;
      line-height: 1.35;
      display: none;
    }

    .match-message.is-match {
      display: block;
      color: var(--match-ok);
    }

    .match-message.is-mismatch {
      display: block;
      color: var(--match-error);
    }

    .form-footer {
      margin-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      width: 100%;
    }

    .back-link {
      font-size: 12px;
      font-weight: 600;
      color: var(--blue);
      text-decoration: none;
      white-space: nowrap;
      transition: color 0.15s ease;
    }

    .back-link:hover {
      color: var(--blue-dark);
      text-decoration: underline;
    }

    .btn-create {
      min-width: 140px;
      height: 38px;
      padding: 0 22px;
      border: none;
      border-radius: 8px;
      background: var(--blue);
      color: #fff;
      font-family: 'Montserrat', sans-serif;
      font-size: 12px;
      font-weight: 600;
      white-space: nowrap;
      cursor: pointer;
      transition: background 0.15s ease;
      box-shadow: 0 3px 10px rgba(68, 138, 255, 0.2);
    }

    .btn-create:hover {
      background: var(--blue-dark);
    }
.mobile-hero-title {
      display: none;
    }

    @media (max-width: 900px) {
      body {
        background: #fff;
      }

      .shell {
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        min-height: 100dvh;
        background: #fff;
      }

      .hero {
        flex: 0 0 auto;
        justify-content: flex-start;
        gap: 0;
        margin-top: 0;
        padding: 0 24px 22px;
        min-height: 0;
        background: linear-gradient(
          180deg,
          #DBE8FF 0%,
          #8AB6FF 27%,
          #448AFF 50%,
          #8AB6FF 77%,
          #DBE8FF 100%
        );
        border-radius: 0 0 28px 28px;
      }

      .logo-wrap {
        margin-top: -28px;
        margin-bottom: -36px;
      }

      .logo {
        width: min(195px, 54vw);
        mix-blend-mode: screen;
        filter: drop-shadow(0 4px 10px rgba(0, 40, 80, 0.12));
      }

      .greeting,
      .hero-sub,
      .btn-signin-link {
        display: none !important;
      }

      .mobile-hero-title {
        display: block;
        margin: -4px 0 0;
        font-size: clamp(22px, 5.8vw, 28px);
        font-weight: 800;
        line-height: 1.2;
        color: #fff;
        letter-spacing: -0.02em;
      }

      .form-panel {
        flex: 1 1 auto;
        width: 100%;
        margin-left: 0;
        border-radius: 0;
        box-shadow: none;
        background: #fffef8;
        padding: 28px 22px 28px;
        min-height: 0;
        align-items: stretch;
        justify-content: flex-start;
      }

      .form-inner {
        width: 100%;
        max-width: 100%;
        min-height: auto;
        flex: 0 0 auto;
      }

      .page-title {
        display: none;
      }

      .section-title {
        font-size: 18px;
        margin-bottom: 18px;
      }

      .section-copy {
        font-size: 13px;
        margin: -8px 0 18px;
        color: #6b6b6b;
      }

      .form-group {
        margin-bottom: 18px;
      }

      .form-group label {
        font-size: 13px;
        margin-bottom: 8px;
      }

      .form-group input,
      .form-group select,
      .input-wrap input {
        height: 48px;
        padding: 0 18px;
        border: 1.5px solid #e4e7ec;
        border-radius: 999px;
        background: #fff;
        font-size: 14px;
        box-shadow: none;
      }

      .form-group select {
        padding-right: 40px;
        appearance: none;
        -webkit-appearance: none;
      }

      .form-group input::placeholder {
        font-style: italic;
        font-size: 13px;
        color: #b0b0b0;
      }

      .form-group input:focus,
      .form-group select:focus,
      .input-wrap input:focus {
        border-color: var(--blue);
        box-shadow: 0 0 0 3px rgba(68, 138, 255, 0.15);
        outline: none;
      }

      .form-footer,
      .form-actions {
        margin-top: 28px;
        padding-top: 0;
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 12px;
        width: 100%;
      }

      .back-link,
      .back-to-signin {
        display: inline-block;
        color: var(--blue);
        font-size: 13px;
        font-weight: 600;
        text-decoration: none;
      }

      .btn-continue,
      .btn-create {
        min-width: 0;
        flex: 0 0 auto;
        height: 44px;
        padding: 0 20px;
        border-radius: 10px;
        font-size: 13px;
        font-weight: 700;
        box-shadow: 0 6px 16px rgba(68, 138, 255, 0.28);
      }
    }

    @media (max-width: 480px) {
      .hero {
        padding: 0 18px 18px;
        min-height: 0;
        border-radius: 0 0 24px 24px;
      }

      .form-panel {
        padding: 24px 18px 24px;
      }

      .form-footer,
      .form-actions {
        flex-wrap: wrap;
      }

      .back-link,
      .back-to-signin {
        font-size: 12px;
      }

      .btn-continue,
      .btn-create {
        padding: 0 16px;
        font-size: 12px;
      }
    }

